CREATE OR REPLACE FUNCTION public.guard_quiz_attempt_insert() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_course uuid; v_test boolean; v_questions jsonb; v_question jsonb; v_answer jsonb; v_index integer:=0; v_correct integer:=0; v_total integer; BEGIN IF auth.uid() IS NULL THEN RETURN NEW; END IF; IF NEW.student_id<>auth.uid() THEN RAISE EXCEPTION 'Cannot submit another student attempt'; END IF; SELECT t.course_id,(t.is_test OR t.is_final),q.questions INTO v_course,v_test,v_questions FROM quizzes q JOIN topics t ON t.id=q.topic_id JOIN courses c ON c.id=t.course_id WHERE q.id=NEW.quiz_id AND t.deleted_at IS NULL AND c.deleted_at IS NULL; IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM enrollments WHERE course_id=v_course AND student_id=auth.uid() AND status='approved') THEN RAISE EXCEPTION 'Approved enrollment required'; END IF; IF v_test AND NOT EXISTS(SELECT 1 FROM course_homework_grades WHERE course_id=v_course AND student_id=auth.uid() AND grade>=5) THEN RAISE EXCEPTION 'Homework grade must be at least 5 before an exam'; END IF; v_total:=jsonb_array_length(v_questions); FOR v_question IN SELECT value FROM jsonb_array_elements(v_questions) LOOP v_answer:=NEW.answers->v_index::text; IF (v_question->>'type'='mcq' AND (v_answer#>>'{}')=(v_question->>'correct')) OR (v_question->>'type'='tf' AND v_answer=v_question->'correct') OR (v_question->>'type'='fill' AND lower(trim(v_answer#>>'{}'))=lower(trim(v_question->>'answer'))) THEN v_correct:=v_correct+1; END IF; v_index:=v_index+1; END LOOP; NEW.score:=CASE WHEN v_total>0 THEN v_correct::numeric/v_total ELSE 0 END; NEW.grade:=greatest(4,least(10,round(4+NEW.score*6)::integer)); NEW.needs_review:=v_test; NEW.reviewed:=false; NEW.final_grade:=NULL; NEW.reviewed_by:=NULL; NEW.teacher_feedback:=NULL; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.guard_quiz_attempt_insert() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER guard_attempt_insert BEFORE INSERT ON public.quiz_attempts FOR EACH ROW EXECUTE FUNCTION public.guard_quiz_attempt_insert();